css:
.page {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 16px;
  align-items: start;
  padding: 12px;
}

.slot {
  container-type: inline-size;
}

.card {
  display: grid;
  gap: 10px;
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.thumb {
  height: 60px;
  background: #fdba74;
  border-radius: 4px;
}

.body h3 {
  margin: 0 0 4px;
}

.body p {
  margin: 0;
}

@container (min-width: 300px) {
  .card {
    grid-template-columns: 80px 1fr;
    align-items: center;
  }

  .thumb {
    height: 80px;
  }
}
